/* 학습 해설
 * KMSAN origin 비용·최초생성과복사 chain의차이
 * 실제 KMSAN compiler hook와 고정 공식 문서 전체를 대조하여 미초기화 추적·metadata 전달·주소 분류·복사·원인 보고·사용 조건을 배웁니다.
 * heap origin은 할당 stack, local origin은 변수 생성 정보와 연결됩니다. unknown 값을 저장할 때 새 chain은 이전 origin과 현재 저장 stack을 연결합니다. 모든 unknown 입력 원인을 완전한 집합으로 동시에 보존하지는 않습니다. chain 깊이 제한은 debug 정보와 메모리 비용의 균형입니다.
 * 생성→저장 A→저장 B→사용의 연결을 그리세요. 실제 core의 최대 7과 cache를 앞 수업과 연결합니다. 추적 구조의 비용과 실제 OS 객체 참조 수를 혼동하지 않습니다.
 */
depot_stack_handle_t __msan_chain_origin(depot_stack_handle_t origin)
{
	depot_stack_handle_t ret = 0;
	unsigned long ua_flags;

	if (!kmsan_enabled || kmsan_in_runtime())
		return ret;

	ua_flags = user_access_save();

	/* Creating new origins may allocate memory. */
	kmsan_enter_runtime();
	ret = kmsan_internal_chain_origin(origin);
	kmsan_leave_runtime();
	user_access_restore(ua_flags);
	return ret;
}
EXPORT_SYMBOL(__msan_chain_origin);

